const Menu = () => { 
    const [open, setState] = useState(false); 

    return (
        <nav>
            <nav className = {`Bar ${open ? '-Open' :'-Closed'}`} onClick = {() => setState(!open)} />
            <nav className = {open? 'Menu-Open' : 'Menu-Closed'}> 
                <ul>
                    <li><a href = "../pages/Home"></a>Home</li>
                    {/* Need to Make the login only appear on home page (in top right?) */}
                    <li><a href = "../pages/Login"></a>Login</li>
                    <li><a href = "../pages/Recapped"></a>My Recapped</li>
                    <li><a href = "../pages/Info"></a>About</li>
                </ul>

            </nav>
        </nav>
    );
}

export default Menu;
